import "dotenv/config";
import { randomUUID } from "node:crypto";
import {
  beforeEach,
  afterEach,
  afterAll,
  describe,
  expect,
  it,
  vi,
} from "vitest";
import { db } from "@/lib/db";
const mocks = vi.hoisted(() => ({
  user: vi.fn(),
  gmail: vi.fn(),
  send: vi.fn(),
}));
vi.mock("@/lib/session", () => ({ requireUser: mocks.user }));
vi.mock("next/cache", () => ({ revalidatePath: vi.fn() }));
vi.mock("@/lib/gmail", async (original) => ({
  ...(await original<typeof import("@/lib/gmail")>()),
  gmailForUser: mocks.gmail,
}));
import { markReplied, undoReply } from "@/lib/recipient-actions";
import * as recipientActions from "@/lib/recipient-actions";
import {
  saveContact,
  importContacts,
  addContactToShortlist,
} from "@/lib/actions";
import { countQuotaUsage } from "@/lib/delivery-usage";
import { clearCompletedHistory } from "@/lib/history";
import { readShortlist, readContacts } from "@/lib/shortlist";
import { readFollowUps } from "@/lib/follow-ups";
import { createCampaign } from "@/lib/campaigns";
import { deliverOne } from "@/lib/inngest";
import { exportAccount } from "@/lib/account";
const enabled = process.env.MAILLOOP_DB_TESTS === "1";
if (
  enabled &&
  !["localhost", "127.0.0.1"].includes(
    new URL(process.env.DATABASE_URL!).hostname,
  )
)
  throw Error("Local database required");
let userId: string,
  otherId: string,
  contactId: string,
  templateId: string,
  campaignId: string;
const address = "[REDACTED_EMAIL]";
async function message(data = {}) {
  return db.send.create({
    data: {
      campaignId,
      contactId,
      recipientEmail: address,
      mimeMessageId: `<${randomUUID()}@mailloop.in>`,
      status: "SENT",
      deliveryState: "DONE",
      sentAt: new Date(),
      ...data,
    },
  });
}
function contactForm() {
  const form = new FormData();
  for (const [k, v] of Object.entries({
    name: "Recipient",
    email: address,
    jobRole: "Engineer",
  }))
    form.set(k, v);
  return form;
}
const request = () => ({
  templateId,
  recipientIds: [contactId],
  recipientRoles: { [contactId]: "Engineer" },
  resendIds: [contactId],
  idempotencyKey: randomUUID(),
  attachResume: false,
});
describe("recipient action exports", () => {
  it("does not expose bounce or do-not-contact server actions", () => {
    expect(recipientActions).not.toHaveProperty("markBounced");
    expect(recipientActions).not.toHaveProperty("doNotContact");
    expect(recipientActions).not.toHaveProperty("markFoundInSent");
  });
});
describe.runIf(enabled)("manual replies and send-only protections", () => {
  beforeEach(async () => {
    vi.resetAllMocks();
    userId = randomUUID();
    otherId = randomUUID();
    await db.user.createMany({
      data: [userId, otherId].map((id) => ({
        id,
        email: `${id}@example.test`,
        gmailAuthorized: true,
        encryptedRefreshToken: "[REDACTED_SECRET]",
      })),
    });
    templateId = (
      await db.template.create({
        data: { userId, name: "Intro", subject: "Hello", body: "Hello" },
      })
    ).id;
    contactId = (
      await db.contact.create({
        data: {
          userId,
          name: "Recipient",
          email: address,
          jobRole: "Engineer",
        },
      })
    ).id;
    campaignId = (
      await db.campaign.create({
        data: { userId, templateId, status: "SENDING" },
      })
    ).id;
    mocks.user.mockResolvedValue({ id: userId });
    mocks.send.mockResolvedValue({
      data: { id: "gmail-message", threadId: "gmail-thread" },
    });
    mocks.gmail.mockResolvedValue({
      email: "[REDACTED_EMAIL]",
      name: "Sender",
      gmail: { users: { messages: { send: mocks.send } } },
    });
  });
  afterEach(async () => {
    await db.user.deleteMany({ where: { id: { in: [userId, otherId] } } });
  });
  afterAll(async () => {
    await db.$disconnect();
  });
  it("authenticates every action, validates IDs and rejects foreign ownership", async () => {
    const send = await message();
    mocks.user.mockRejectedValueOnce(Error("Authentication required"));
    await expect(markReplied(send.id)).rejects.toThrow(
      "Authentication required",
    );
    mocks.user.mockRejectedValueOnce(Error("Authentication required"));
    await expect(undoReply(send.id)).rejects.toThrow("Authentication required");
    expect(await markReplied("invalid")).toMatchObject({ ok: false });
    expect(await undoReply("invalid")).toMatchObject({ ok: false });
    mocks.user.mockResolvedValue({ id: otherId });
    for (const action of [markReplied, undoReply])
      expect(await action(send.id)).toMatchObject({ ok: false });
  });
  it("marks replies idempotently, clears requested reminders and excludes due reminders", async () => {
    const send = await message({
      sentAt: new Date(Date.now() - 10 * 86400000),
    });
    expect((await readFollowUps(userId, 7)).total).toBe(1);
    await db.contact.update({
      where: { id: contactId, userId },
      data: { followUpRequestedAt: new Date() },
    });
    expect(await markReplied(send.id)).toMatchObject({ ok: true });
    const first = await db.send.findFirstOrThrow({
      where: { id: send.id, campaign: { userId } },
    });
    expect(await markReplied(send.id)).toMatchObject({ ok: true });
    expect(
      (
        await db.send.findFirstOrThrow({
          where: { id: send.id, campaign: { userId } },
        })
      ).replyMarkedAt,
    ).toEqual(first.replyMarkedAt);
    expect(
      (await db.contact.findFirstOrThrow({ where: { id: contactId, userId } }))
        .followUpRequestedAt,
    ).toBeNull();
    expect((await readFollowUps(userId, 7)).total).toBe(0);
  });
  it("undoes reply marks idempotently and restores due reminders without changing delivery evidence", async () => {
    const sentAt = new Date(Date.now() - 10 * 86400000);
    const send = await message({ sentAt, gmailMessageId: "accepted-message" });
    await markReplied(send.id);
    expect((await readFollowUps(userId, 7)).total).toBe(0);
    expect(await undoReply(send.id)).toMatchObject({ ok: true });
    expect(await undoReply(send.id)).toMatchObject({ ok: true });
    expect(
      await db.send.findFirstOrThrow({
        where: { id: send.id, campaign: { userId } },
      }),
    ).toMatchObject({
      status: "SENT",
      replyMarkedAt: null,
      sentAt,
      deliveryState: "DONE",
      gmailMessageId: "accepted-message",
    });
    expect((await readFollowUps(userId, 7)).total).toBe(1);
    expect(mocks.gmail).not.toHaveBeenCalled();
  });
  it("rejects undo for other statuses, deleted history, and accounts being deleted", async () => {
    for (const status of ["QUEUED", "FAILED", "CANCELLED"] as const) {
      const send = await message({ status });
      expect(await undoReply(send.id)).toMatchObject({ ok: false });
      expect(
        (
          await db.send.findFirstOrThrow({
            where: { id: send.id, campaign: { userId } },
          })
        ).status,
      ).toBe(status);
    }
    const send = await message({
      status: "REPLIED",
      replyMarkedAt: new Date(),
      historyDeletedAt: new Date(),
    });
    expect(await undoReply(send.id)).toMatchObject({ ok: false });
    const active = await message({
      status: "REPLIED",
      replyMarkedAt: new Date(),
    });
    await db.user.update({
      where: { id: userId },
      data: { deletionRequestedAt: new Date() },
    });
    expect(await undoReply(active.id)).toMatchObject({ ok: false });
    expect(
      (
        await db.send.findFirstOrThrow({
          where: { id: active.id, campaign: { userId } },
        })
      ).status,
    ).toBe("REPLIED");
  });
  it("ages uncertain quota at the original attempt while preserving permanent duplicate blocking", async () => {
    const attemptedAt = new Date();
    const send = await message({
      status: "FAILED",
      deliveryState: "UNCERTAIN",
      sentAt: null,
      attemptedAt,
    });
    expect(
      await countQuotaUsage(
        userId,
        db,
        new Date(attemptedAt.getTime() + 86400000 - 1),
      ),
    ).toBe(1);
    expect(
      await countQuotaUsage(
        userId,
        db,
        new Date(attemptedAt.getTime() + 86400000 + 1),
      ),
    ).toBe(0);
    await db.send.updateMany({
      where: { id: send.id, campaign: { userId } },
      data: { attemptedAt: new Date(Date.now() - 25 * 3600000) },
    });
    expect(await countQuotaUsage(userId)).toBe(0);
    await expect(createCampaign(userId, request())).rejects.toThrow("skipped");
    await deliverOne(userId, send.id);
    expect(mocks.send).not.toHaveBeenCalled();
    expect(await clearCompletedHistory(userId)).toBe(0);
    expect(
      await db.send.findFirst({ where: { id: send.id, campaign: { userId } } }),
    ).not.toBeNull();
  });
  it("preserves delivery evidence across contacts, reminders and history clearing", async () => {
    expect((await readShortlist(userId)).total).toBe(1);
    expect(await addContactToShortlist(contactId)).toMatchObject({ ok: true });
    expect(await saveContact(contactForm())).toMatchObject({ ok: true });
    const campaign = await createCampaign(userId, request());
    const send = await db.send.findFirstOrThrow({
      where: { campaignId: campaign.id, campaign: { userId } },
    });
    await deliverOne(userId, send.id);
    expect(mocks.send).toHaveBeenCalledOnce();
    await db.send.updateMany({
      where: { id: send.id, campaign: { userId } },
      data: {
        sentAt: new Date(Date.now() - 10 * 86400000),
        bouncedAt: new Date(),
      },
    });
    expect((await readFollowUps(userId, 7)).total).toBe(1);
    const exported = await exportAccount(userId);
    expect(exported).not.toHaveProperty("recipientSuppressions");
    expect(
      exported.campaigns.flatMap((c) => c.sends).find((s) => s.id === send.id)
        ?.bouncedAt,
    ).toBeInstanceOf(Date);
    await clearCompletedHistory(userId);
    expect((await readContacts(userId)).total).toBe(0);
    await db.contact.updateMany({
      where: { id: contactId, userId },
      data: { archivedAt: new Date() },
    });
    expect(await saveContact(contactForm())).toMatchObject({ ok: true });
  });
  it("imports an address into the shortlist", async () => {
    const email = "[REDACTED_EMAIL]";
    expect(
      await importContacts([{ name: "Legacy", email, jobRole: "Engineer" }]),
    ).toMatchObject({
      ok: true,
      message: "1 contacts imported. 0 rows skipped.",
    });
    expect((await readShortlist(userId)).total).toBe(2);
  });
  it("supports legacy REPLIED rows without manual timestamps", async () => {
    const send = await message({
      status: "REPLIED",
      replyMarkedAt: null,
      sentAt: new Date(Date.now() - 10 * 86400000),
    });
    expect((await readFollowUps(userId, 7)).total).toBe(0);
    expect(await undoReply(send.id)).toMatchObject({ ok: true });
    expect((await readFollowUps(userId, 7)).total).toBe(1);
    expect(await markReplied(send.id)).toMatchObject({ ok: true });
  });
  it("matches manual replies and Undo by immutable recipient address after contact edits", async () => {
    const send = await message({
      sentAt: new Date(Date.now() - 10 * 86400000),
    });
    await db.contact.updateMany({
      where: { id: contactId, userId },
      data: { email: "[REDACTED_EMAIL]", archivedAt: new Date() },
    });
    const replacement = await db.contact.create({
      data: { userId, name: "Recipient", email: address, jobRole: "Engineer" },
    });
    expect((await readFollowUps(userId, 7)).contacts.map((c) => c.id)).toEqual([
      replacement.id,
    ]);
    expect(await markReplied(send.id)).toMatchObject({ ok: true });
    expect((await readFollowUps(userId, 7)).total).toBe(0);
    expect(await undoReply(send.id)).toMatchObject({ ok: true });
    expect((await readFollowUps(userId, 7)).contacts.map((c) => c.id)).toEqual([
      replacement.id,
    ]);
  });
  it("rejects marking queued, failed, cancelled and uncertain sends replied", async () => {
    for (const status of ["QUEUED", "FAILED", "CANCELLED"] as const) {
      const send = await message({
        status,
        deliveryState: status === "FAILED" ? "UNCERTAIN" : "DONE",
      });
      expect(await markReplied(send.id)).toMatchObject({ ok: false });
    }
  });
  it("never resends an uncertain attempt after a worker recovers", async () => {
    const send = await message({
      status: "QUEUED",
      deliveryState: "READY",
      sentAt: null,
    });
    mocks.send.mockRejectedValueOnce(Error("timeout"));
    await deliverOne(userId, send.id);
    await deliverOne(userId, send.id);
    expect(mocks.send).toHaveBeenCalledOnce();
    expect(
      await db.send.findFirst({ where: { id: send.id, campaign: { userId } } }),
    ).toMatchObject({
      status: "FAILED",
      deliveryState: "UNCERTAIN",
      sentConfirmedManuallyAt: null,
    });
    expect(await countQuotaUsage(userId)).toBe(1);
    await expect(createCampaign(userId, request())).rejects.toThrow("skipped");
  });
});
